// CertificatesPage.js
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';

export function CertificatesPage() {
  const [certs, setCerts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.get('/api/certificates/my').then(r => setCerts(r.data)).catch(() => {}).finally(() => setLoading(false));
  }, []);

  return (
    <div style={{ minHeight: '100vh', paddingTop: 90 }}>
      <div className="page-container" style={{ padding: '40px 24px' }}>
        <div style={{ marginBottom: 36 }}>
          <h1 style={{ fontSize: 32, fontWeight: 900, marginBottom: 8 }}>
            My <span style={{ background: 'linear-gradient(135deg, #ffd700, #f72585)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>Certificates</span>
          </h1>
          <p style={{ color: '#6b6490' }}>Your verified achievements</p>
        </div>

        {loading ? <div className="loader" style={{ margin: '60px auto' }} /> :
          certs.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '80px 0', border: '1px dashed rgba(255,215,0,0.3)', borderRadius: 20 }}>
              <div style={{ fontSize: 64, marginBottom: 16 }}>🏆</div>
              <h3 style={{ fontSize: 20, fontWeight: 700, marginBottom: 8 }}>No certificates yet</h3>
              <p style={{ color: '#6b6490' }}>Complete a course to earn your first certificate!</p>
            </div>
          ) : (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: 24 }}>
              {certs.map((cert, i) => (
                <div key={cert._id} className="glass" style={{ padding: 28, borderRadius: 20, border: '1px solid rgba(255,215,0,0.25)', animation: `fadeUp 0.5s ease ${i * 0.08}s both` }}>
                  <div style={{ textAlign: 'center', marginBottom: 20 }}>
                    <div style={{ fontSize: 56, marginBottom: 12 }}>🏆</div>
                    <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: '0.15em', color: '#ffd700', textTransform: 'uppercase', marginBottom: 8 }}>Certificate of Completion</div>
                    <h3 style={{ fontSize: 18, fontWeight: 800, color: '#f0eeff', lineHeight: 1.3 }}>{cert.course?.title || 'Course'}</h3>
                  </div>
                  <div style={{ borderTop: '1px solid rgba(255,215,0,0.15)', paddingTop: 16, display: 'flex', flexDirection: 'column', gap: 8 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 13 }}>
                      <span style={{ color: '#6b6490' }}>Certificate ID</span>
                      <span style={{ fontFamily: 'monospace', color: '#ffd700', fontWeight: 700 }}>{cert.certificateId}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 13 }}>
                      <span style={{ color: '#6b6490' }}>Issued</span>
                      <span style={{ color: '#b8b0d8' }}>{new Date(cert.issuedAt).toLocaleDateString()}</span>
                    </div>
                  </div>
                  <a href={`http://localhost:5000/api/certificates/download/${cert.certificateId}`}
                    className="btn btn-primary" style={{ width: '100%', justifyContent: 'center', marginTop: 20, textDecoration: 'none' }}>
                    ⬇️ Download PDF
                  </a>
                </div>
              ))}
            </div>
          )}
      </div>
    </div>
  );
}

export default CertificatesPage;
